    slug: "network-policy",
    title: "Kubernetes NetworkPolicy (Zero-Trust)",
    category: "Security",
    duration: "60 min",
    level: "Hands-on",
    tagline: "frontend → backend → database. Allow the chain, deny frontend → database, prove it.",
    pipeline: ["frontend", "backend", "database"],
