export const troubleshootingFlow: { layer: string; question: string; commands: string[]; fix: string }[] = [
  { layer: "DNS", question: "Does the name resolve to the ALB?", commands: ["dig +short mycompany.com", "nslookup mycompany.com"], fix: "Fix hosted zone / delegation / alias record." },
  { layer: "Route", question: "Is there a path (IGW / NAT / local)?", commands: ["aws ec2 describe-route-tables --filters Name=vpc-id,Values=<vpc>"], fix: "Restore IGW / NAT / association." },
  { layer: "Security Group", question: "Is the port open from the right source?", commands: ["aws ec2 describe-security-groups --group-ids <sg>", "nc -vz <host> <port>"], fix: "Allow port from referencing SG, never 0.0.0.0/0 to data." },
  { layer: "Network ACL", question: "Is the subnet firewall denying?", commands: ["aws ec2 describe-network-acls --filters Name=vpc-id,Values=<vpc>"], fix: "Keep default allow; remove stray denies." },
  { layer: "Load Balancer", question: "Listener + cert + redirect correct?", commands: ["aws elbv2 describe-listeners --load-balancer-arn <alb>", "curl -I http://mycompany.com"], fix: "Re-attach ACM cert (same region), fix :80→:443." },
  { layer: "Target Group", question: "Are targets healthy?", commands: ["aws elbv2 describe-target-health --target-group-arn <tg>"], fix: "Align healthcheck path/port with readiness probe." },
  { layer: "Service", question: "Selector + ports correct?", commands: ["kubectl get svc -n prod", "kubectl describe svc <s> -n prod"], fix: "Fix selector labels, port/targetPort." },
  { layer: "Endpoint", question: "Does the Service have members?", commands: ["kubectl get endpoints <s> -n prod"], fix: "Empty = selector or readiness wrong." },
  { layer: "Pod", question: "Running AND Ready?", commands: ["kubectl get pods -n prod", "kubectl describe pod <p> -n prod"], fix: "Readiness gates, resources, image." },
  { layer: "Application", question: "What do logs say?", commands: ["kubectl logs -n prod <p>", "kubectl logs -n prod <p> --previous"], fix: "Fix app/config; check /healthz deps." },
  { layer: "Database", question: "Reachable + authed?", commands: ["nc -vz <rds> 5432", "nslookup <rds>"], fix: "SG :5432 from app SG; secret/rotation; private endpoint." },
];

